import csv, re, json
from datetime import date, datetime

def norm(s): return (s or '').strip()
def norm_id(s): return norm(s).upper()
def parse_money(s):
    s=norm(s).replace('$','').replace(',','')
    neg=s.startswith('(') and s.endswith(')')
    if neg: s=s[1:-1]
    return -float(s) if neg else float(s)
def parse_num(s): return float(norm(s))
def parse_date(s): return datetime.strptime(norm(s),'%Y-%m-%d').date()

lines_raw=list(csv.DictReader(open('input/commission_lines.csv')))
# unique by line_id, preserving first occurrence
lines=[]
seen_line_ids=set()
for r in lines_raw:
    lid=norm(r['line_id'])
    if lid in seen_line_ids:
        continue
    seen_line_ids.add(lid)
    r={k:norm(v) for k,v in r.items()}
    r['deal_id_norm']=norm_id(r['deal_id'])
    r['customer_id_norm']=norm_id(r['customer_id'])
    r['reported_rate']=parse_num(r['reported_rate_pct'])
    r['revenue']=parse_num(r['revenue_usd'])
    lines.append(r)

cust={}
for r in csv.DictReader(open('input/customer_master.csv')):
