    cust[norm_id(r['customer_id'])]=r

led_raw=list(csv.DictReader(open('input/netsuite_revenue_june.csv')))
led=[]
seen_post=set()
repeated_post=[]
for r in led_raw:
    pid=norm(r['posting_id'])
    if pid in seen_post:
        repeated_post.append(pid)
        continue
    seen_post.add(pid)
    r={k:norm(v) for k,v in r.items()}
    r['deal_norm']=norm_id(r['deal_ref'])
    r['customer_norm']=norm_id(r['customer_id'])
    r['amount']=parse_money(r['amount_usd'])
    r['date']=parse_date(r['posting_date'])
    r['june']=r['date'].year==2026 and r['date'].month==6
    led.append(r)

# reversals: negative amount or memo mentions credit note against
for p in led:
    p['is_reversal']=p['amount']<0 or 'credit note against' in p['memo'].lower()
# identify reversed original posting_ids from memo
rev_targets=set()
for p in led:
    m=re.search(r'against\s+(P-\d+)', p['memo'], re.I)
    if m: rev_targets.add(m.group(1).upper())
for p in led:
    p['reversed_by_later']=p['posting_id'].upper() in rev_targets

# exceptions
exc={}
for r in csv.DictReader(open('input/commission_exceptions.csv')):
    r={k:norm(v) for k,v in r.items()}
    d=norm_id(r['deal_id'])
    eff=parse_date(r['effective_from']); to=parse_date(r['effective_to'])
    active=r['status'].lower()=='active' and eff<=date(2026,6,30)<=to
    if active and d not in exc:
        exc[d]={'code':r['exception_code'],'rate':parse_num(r['approved_rate_pct']),'from':r['effective_from'],'to':r['effective_to']}

# co-sell
cosell={}
for r in csv.DictReader(open('input/co_sell_register.csv')):
    r={k:norm(v) for k,v in r.items()}
    d=norm_id(r['deal_id'])
    cosell.setdefault(d,[]).append({'partner':r['partner'],'share':parse_num(r['share_pct']),'status':r['status'].lower()})

# group lines by deal
from collections import defaultdict
deal_lines=defaultdict(list)
for l in lines:
    deal_lines[l['deal_id_norm']].append(l)

cosell_ok={}
for d,regs in cosell.items():
    ok = all(x['status']=='active' for x in regs)
    partners=[x['partner'] for x in regs]
    line_partners=[l['source_report'] for l in deal_lines.get(d,[])]
    ok = ok and sorted(partners)==sorted(line_partners) and len(partners)==len(line_partners)
    ok = ok and sum(x['share'] for x in regs)==100
    cosell_ok[d]=ok

# ledger net by deal
def june_postings(d):
    return [p for p in led if p['deal_norm']==d and p['june']]

def net_june(d):
    return sum(p['amount'] for p in june_postings(d))

def customer_for_deal(d):
    posts=june_postings(d)
    # record nothing for reversed original or reversal for this purpose
    posts=[p for p in posts if not (p['is_reversal'] or p['reversed_by_later'])]
    if posts:
        return posts[0]['customer_norm']
    # no June posting, use partner's customer_id from first line
    return deal_lines[d][0]['customer_id_norm'] if deal_lines.get(d) else None

def end_user_type(cust_id):
    c=cust.get(cust_id)
    if not c: return None
    if c['account_class'].lower()=='house': return 'house'
    return 'new' if parse_date(c['first_invoice_date'])>=date(2025,7,1) else 'renewal'

def policy_rate(d, cust_id):
    if d in exc:
        return exc[d]['rate']
